```json
{
  "root_causes": [
    {
      "service": "ts-travel2-service",
      "fault_kind": "application_method_slow",
      "evidence": [
        {"kind": "trace", "sql": "SELECT span_name, attr_span_kind, count(*) n, round(quantile_cont(duration/1e6,0.5),1) p50_ms, round(quantile_cont(duration/1e6,0.95),1) p95_ms FROM abnormal_traces WHERE service_name='ts-travel2-service' AND span_name LIKE 'Travel2Controller.%' AND attr_span_kind='Internal' GROUP BY 1,2 ORDER BY 3 DESC", "claim": "Travel2Controller.queryInfo and getTripAllDetailInfo/getRouteByTripId self-time p50 ~3.6-11 s in abnormal, versus ~11-86 ms in normal."},
        {"kind": "trace", "sql": "SELECT span_name, attr_span_kind, count(*) n, round(quantile_cont(duration/1e6,0.5),1) p50_ms FROM abnormal_traces WHERE service_name='ts-travel2-service' AND span_name IN ('TripRepository.findAll','TripRepository.findByTripId','SELECT Trip','SELECT ts.trip2','Transaction.commit') GROUP BY 1,2", "claim": "Travel2 DB spans and repository calls stay at about 1-4 ms in the abnormal window, so the extra time sits in the controller method itself."},
        {"kind": "trace", "sql": "SELECT service_name, span_name, count(*) n, round(quantile_cont(duration/1e6,0.95),1) p95_ms FROM abnormal_traces WHERE service_name='ts-travel2-service' AND attr_span_kind='Server' GROUP BY 1,2 ORDER BY 4 DESC", "claim": "travel2 server spans for trip_detail, trips/left and routes/{tripId} reach 3.7-18.5 s p95 in the abnormal window."}
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-travel2-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {"kind": "trace", "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, round(quantile_cont(c.duration/1e6,0.5),1) callee_srv_p50_ms, round(quantile_cont(p.duration/1e6,0.5),1) caller_client_p50_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.trace_id=p.trace_id AND c.parent_span_id=p.span_id WHERE c.service_name='ts-travel2-service' AND c.attr_span_kind='Server' AND p.attr_span_kind='Client' AND p.service_name<>c.service_name GROUP BY 1,2", "claim": "ts-route-plan-service client calls to ts-travel2-service take ~3.7 s p50 in abnormal, because travel2 is slow."}
      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {"kind": "trace", "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, round(quantile_cont(c.duration/1e6,0.5),1) callee_srv_p50_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.trace_id=p.trace_id AND c.parent_span_id=p.span_id WHERE c.service_name='ts-route-plan-service' AND c.attr_span_kind='Server' AND p.attr_span_kind='Client' AND p.service_name='ts-travel-plan-service' GROUP BY 1,2", "claim": "ts-travel-plan-service calls to ts-route-plan-service take ~14.9 s p50 in abnormal, inheriting route-plan's slowness."}
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, round(quantile_cont(duration/1e6,0.95),1) p95_ms FROM abnormal_traces WHERE service_name IN ('ts-travel-plan-service','ts-ui-dashboard') AND attr_span_kind='Server' GROUP BY 1,2,3 ORDER BY 1,2", "claim": "travel-plan server spans reach ~18-26 s p95 and ts-ui-dashboard server p95 rises to ~3.7 s, versus ~221 ms normal."}
      ]
    }
  ]
}
```

